<?php
namespace exface\Core\CommonLogic\Utils;

/**
 * Compresses widget ids into short URL-safe tokens and back.
 * 
 * Autogenerated widget ids are paths from the page root (see `UiPage::generateWidgetId()`), so they grow
 * with every nested dialog - and grow very fast if dialogs open each other in a loop. Wherever such ids
 * end up in URLs (route hashes, view names, GET parameters like `element`), they should be encoded via
 * `encode()`. The server decodes them centrally in `GenericTask::setWidgetIdTriggeredBy()`, so facades
 * only need to care about encoding.
 * 
 * Tokens look like `wz-c0ksSQxJTMpJjXeB...`: the prefix followed by base64url(raw deflate(id)). They only 
 * contain `[A-Za-z0-9_-]` - in particular no dots - so they are safe in URL paths, UI5 view names and DOM ids.
 * Deflate replaces repeated substrings by back-references, so ids of looping dialogs (the same segments 
 * repeated over and over) remain almost constant in size.
 * 
 * This encoding is NOT a security measure - it is fully reversible and must not be used to hide anything.
 * 
 * To read an encoded id while debugging, use `WidgetIdEncoder::decode('wz-...')`.
 */
class WidgetIdEncoder
{
    /**
     * Marks encoded widget ids
     * 
     * @var string
     */
    const PREFIX = 'wz-';
    
    /**
     * Max. size of a decoded widget id in bytes - protects against decompression bombs passed via URL
     * 
     * @var int
     */
    const MAX_DECODED_LENGTH = 1048576;
    
    /**
     * Compresses the given widget id into a short URL-safe token
     * 
     * @param string $widgetId
     * @return string
     */
    public static function encode(string $widgetId) : string
    {
        return self::PREFIX . rtrim(strtr(base64_encode(gzdeflate($widgetId, 9)), '+/', '-_'), '='); 
    }
    
    /**
     * Restores a widget id encoded via `encode()`. Plain (not encoded) ids are returned as-is.
     * 
     * Anything, that does not look like a valid token (wrong prefix, invalid characters, broken deflate stream)
     * is treated as a plain widget id. This keeps old URLs working and makes sure, a user-defined widget id,
     * that accidentally starts with the prefix, is still found.
     * 
     * The input usually comes from URLs and is untrusted: decoding is limited to `gzinflate()` with a size cap
     * and the result must only be used to look up widgets - never executed or rendered.
     * 
     * @param string $encodedOrPlainId
     * @return string
     */
    public static function decode(string $encodedOrPlainId) : string
    {
        if (strncmp($encodedOrPlainId, self::PREFIX, strlen(self::PREFIX)) !== 0) {
            return $encodedOrPlainId;
        }
        $token = substr($encodedOrPlainId, strlen(self::PREFIX));
        if ($token === '' || preg_match('/^[A-Za-z0-9_-]+$/', $token) !== 1) {
            return $encodedOrPlainId;
        }
        $deflated = base64_decode(strtr($token, '-_', '+/'), true);
        if ($deflated === false) {
            return $encodedOrPlainId;
        }
        $decoded = @gzinflate($deflated, self::MAX_DECODED_LENGTH);
        if ($decoded === false || $decoded === '') {
            return $encodedOrPlainId;
        }
        return $decoded;
    }
}